import{useState}from'react';import{ArrowRight,Check,GitCompareArrows,IndianRupee,Sparkles,Trophy}from'lucide-react';import api,{message}from'./api';import{PageTitle}from'./Features';
const empty=name=>({name,price:'',expectedUses:50,warrantyMonths:12,needRating:3,qualityRating:3,ownsAlternative:false});const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v||0);
export default function ComparePage(){const[a,setA]=useState(empty('Option A')),[b,setB]=useState(empty('Option B')),[result,setResult]=useState(),[error,setError]=useState('');async function submit(e){e.preventDefault();try{const{data}=await api.post('/comparisons',{first:{...a,price:Number(a.price),expectedUses:Number(a.expectedUses),warrantyMonths:Number(a.warrantyMonths)},second:{...b,price:Number(b.price),expectedUses:Number(b.expectedUses),warrantyMonths:Number(b.warrantyMonths)}});setResult(data);setError('')}catch(x){setError(message(x))}}return <><PageTitle eyebrow="VALUE COMPARATOR" title="Compare value—not marketing" copy="Estimate cost per use and weigh need, quality, warranty, and products you already own."/><form className="compare-layout" onSubmit={submit}><Option title="First option" value={a} set={setA}/><div className="versus"><GitCompareArrows/><span>VS</span></div><Option title="Second option" value={b} set={setB}/><div className="compare-submit">{error&&<div className="error">{error}</div>}<button className="primary"><Sparkles/>Compare long-term value</button></div></form>{result&&<section className="comparison-result"><div className="winner"><Trophy/><span><small>STRONGER VALUE</small><h2>{result.winner}</h2><p>{result.explanation}</p></span></div><div className="value-results">{[result.first,result.second].map(x=><article className={x.name===result.winner?'best':''} key={x.name}><span>{x.name}</span><strong>{x.valueScore}<small>/100</small></strong><div><em>Price</em><b>{money(x.price)}</b></div><div><em>Cost per use</em><b>{money(x.costPerUse)}</b></div>{x.notes.map(n=><p key={n}><Check/>{n}</p>)}</article>)}</div></section>}</>}
function Option({title,value,set}){return <section className="compare-card"><span className="compare-label">{title}</span><label>Product name<input required value={value.name} onChange={e=>set({...value,name:e.target.value})}/></label><label>Price<div className="money-input"><IndianRupee/><input required min="1" type="number" value={value.price} onChange={e=>set({...value,price:e.target.value})}/></div></label><div className="two-fields"><label>Expected lifetime uses<input required min="1" type="number" value={value.expectedUses} onChange={e=>set({...value,expectedUses:e.target.value})}/></label><label>Warranty months<input min="0" type="number" value={value.warrantyMonths} onChange={e=>set({...value,warrantyMonths:e.target.value})}/></label></div><Rating label="How much do you need it?" value={value.needRating} set={v=>set({...value,needRating:v})}/><Rating label="Expected quality" value={value.qualityRating} set={v=>set({...value,qualityRating:v})}/><label className="check-row"><input type="checkbox" checked={value.ownsAlternative} onChange={e=>set({...value,ownsAlternative:e.target.checked})}/><span>I already own an alternative</span></label></section>}
function Rating({label,value,set}){return <div className="rating-field"><span>{label}</span><div>{[1,2,3,4,5].map(n=><button type="button" className={n<=value?'active':''} onClick={()=>set(n)} key={n}>{n}</button>)}</div></div>}
